/**
 * 游客模式的生成提示词注入。
 *
 * 提供 dialogue / story / message 三种场景的输出格式约束，
 * 通过 generate({ injects }) 单次注入，不污染全局 injectPrompts。
 */

export type CustomerGenerationKind = 'dialogue' | 'story' | 'message';

type InjectItem = Omit<InjectionPrompt, 'id'>;

function makeDialoguePrompt(speaker: string): string {
  return [
    `[输出格式要求]`,
    `当前互动类型：Galgame 短对话。`,
    ``,
    `<content> 内只写当前角色真正说出口的台词，每行格式：`,
    `角色名: 台词`,
    ``,
    `一行对应一页台词，可以有多行但保持简短。`,
    `当前说话人：${speaker}。`,
    ``,
    `禁止：`,
    `- 旁白、环境描写、角色内心独白`,
    `- 信息判定、行为逻辑、思维过程`,
    `- 台词预演或多种可能`,
    `- 代替 <user> 说话或行动`,
    `- 正文开头的孤立符号如 -`,
    `- 把变量更新写进 <content>`,
    ``,
    `变量更新放在 </content> 之后按已有格式输出。`,
  ].join('\n');
}

function makeStoryPrompt(speaker: string | null): string {
  const speakerLine = speaker ? `当前主要角色：${speaker}。\n` : '';
  return [
    `[输出格式要求]`,
    `当前互动类型：完整 AIRP 正文。`,
    ``,
    `正文放在 <content>...</content> 中。`,
    `使用当前已激活的地点、员工、项目和关系事实继续场景。`,
    speakerLine,
    `可以描写：环境、角色动作、表情、语言、成年人之间自愿发生的亲密内容。`,
    `用户已输入的动作可以承接和描写结果。`,
    ``,
    `禁止：`,
    `- 思维链、分析、信息判定、行为逻辑、心里话`,
    `- 代替 <user> 决定未输入的行动、心理和台词`,
    `- 凭空加入没有激活的主要角色`,
    `- 重复罗列变量或当前状态`,
    `- 把变量更新写进 <content>`,
    ``,
    `如果剧情确实推进时间，可在 </content> 后输出：`,
    `<time>YYYY年MM月DD日 星期X HH:mm</time>`,
    `没有明确时间推进时不要输出虚假的时间变化。`,
    ``,
    `变量更新放在最后按已有格式输出。`,
  ].join('\n');
}

function makeMessagePrompt(speaker: string): string {
  return [
    `[输出格式要求]`,
    `当前互动类型：联系人线上消息。`,
    ``,
    `<content> 内只写当前员工发回的一条消息，格式：`,
    `${speaker}: 回复内容`,
    ``,
    `这是线上消息，不是面对面场景。`,
    ``,
    `禁止：`,
    `- 环境旁白或动作描写`,
    `- 代替用户回复`,
    `- 描写双方已经见面`,
    `- 把员工当前位置写成用户所在地`,
    `- 写成长篇正文`,
    `- 把变量更新写进 <content>`,
    ``,
    `回复长度符合聊天软件消息习惯。`,
    `邀约可以接受、犹豫、拒绝或商量时间，按人设和关系决定。`,
    `邀约成功只代表约定成立，不代表见面已经发生。`,
    ``,
    `变量更新放在 </content> 之后按已有格式输出。`,
  ].join('\n');
}

/**
 * 根据当前生成入口种类和说话人，构建游客模式的单次注入提示词。
 * speaker 为 null 或空字符串时，story 提示词不会输出"当前主要角色"行。
 */
export function makeCustomerGenerationInjects(kind: CustomerGenerationKind, speaker: string | null): InjectItem[] {
  let content: string;
  switch (kind) {
    case 'dialogue':
      content = makeDialoguePrompt(speaker || '');
      break;
    case 'story':
      content = makeStoryPrompt(speaker || null);
      break;
    case 'message':
      content = makeMessagePrompt(speaker || '');
      break;
    default:
      content = makeDialoguePrompt(speaker || '');
  }

  return [
    {
      position: 'in_chat',
      depth: 1,
      role: 'system',
      content,
      should_scan: false,
    },
  ];
}
