emplate>\n  <section\n    class=\"customer-play-layer\"\n    :class=\"{ 'is-menu-open': menuOpen, 'is-story-open': storyOpen }\"\n    aria-label=\"游客玩法\"\n  >\n    <template v-if=\"!menuOpen && !storyOpen\">\n      <header class=\"customer-brand\">\n        <span class=\"customer-seal\">汤</span>\n        <span><strong>未开之花</strong><small>游客视角</small></span>\n      </header>\n\n      <aside class=\"customer-status\" aria-label=\"游客状态\">\n        <div class=\"visit-plaque\">\n          <b>{{ String(state.到店次数).padStart(2, '0') }}</b>\n          <span>到店次数</span>\n        </div>\n        <div class=\"status-row\">\n          <span>资金</span>\n          <strong>{{ yuan(state.资金) }}</strong>\n        </div>\n        <div class=\"status-row\">\n          <span>指名</span>\n          <strong>{{ state.当前指名?.员工 || '未指名' }}</strong>\n        </div>\n        <div class=\"status-row\">\n          <span>预约</span>\n          <strong>{{ state.当前服务?.项目 || '暂无' }}</strong>\n        </div>\n      </aside>\n\n      <div class=\"customer-clock\">\n        <span>{{ state.日期 }}</span>\n        <b>{{ state.时间 }}</b>\n        <span>{{ state.地点 }}</span>\n      </div>\n\n      <div v-if=\"currentEmployee\" class=\"customer-sprite\" aria-hidden=\"true\">\n        <img :src=\"spriteUrl\" alt=\"\" />\n        <div class=\"sprite-caption\">\n          <strong>{{ currentEmployee.姓名 }}</strong>\n          <span>{{ currentEmployee.评级 }}级 · {{ relationshipStage }}</span>\n        </div>\n      </div>\n\n      <nav class=\"customer-actions\" aria-label=\"游客快捷操作\">\n        <template v-if=\"state.当前服务?.状态 === '进行中'\">\n          <button type=\"button\" :disabled=\"busy\" @click=\"$emit('talk', state.当前服务.员工)\">\n            <span>继续交谈</span><b>›</b>\n          </button>\n          <button type=\"button\" :disabled=\"busy\" @click=\"$emit('extra', state.当前服务.员工)\">\n            <span>额外服务</span><b>＋</b>\n          </button>\n          <button type=\"button\" :disabled=\"busy\" @click=\"$emit('finish-service')\"><span>结束服务</span><b>■</b></button>\n        </template>\n        <template v-else>\n          <button type=\"button\" :disabled=\"busy\" @click=\"$emit('open-menu', 'projects')\">\n            <span>选择服务</span><b>›</b>\n          </button>\n          <button type=\"button\" :disabled=\"busy\" @click=\"$emit('open-menu', 'nomination')\">\n            <span>指名</span><b>♙</b>\n          </button>\n          <button type=\"button\" :disabled=\"busy\" @click=\"$emit('open-menu', 'relationship')\">\n            <span>关系</span><b>♡</b>\n          </button>\n          <button type=\"button\" :disabled=\"busy\" @click=\"$emit('open-menu', 'contacts')\">\n            <span>联系人</span><b>⌁</b>\n          </button>\n          <button type=\"button\" :disabled=\"busy\" @click=\"$emit('free-airp')\"><span>自由行动</span><b>＋</b></button>\n        </template>\n      </nav>\n\n      <button class=\"customer-dialogue\" type=\"button\" @click=\"$emit('next-dialogue')\">\n        <span class=\"dialogue-name\">{{ dialoguePage.speaker || state.对话.说话人 }}</span>\n        <span class=\"dialogue-body\">{{ dialoguePage.text }}</span>\n        <span v-if=\"state.对话.台词页.length > 1\" class=\"dialogue-count\">\n          {{ state.对话.当前页 + 1 }} / {{ state.对话.台词页.length }}\n        </span>\n      </button>\n    </template>\n\n    <section v-if=\"menuOpen\" class=\"customer-menu-layer\" aria-label=\"游客菜单\">\n      <nav class=\"customer-menu-tabs\" aria-label=\"游客菜单分类\">\n        <button\n          v-for=\"tab in tabs\"\n          :key=\"tab.key\"\n          type=\"button\"\n          :class=\"{ 'is-active': view === tab.key }\"\n          @click=\"$emit('open-menu', tab.key)\"\n        >\n          {{ tab.title }}\n        </button>\n      </nav>\n\n      <article class=\"customer-menu-main\">\n        <header class=\"customer-menu-head\">\n          <div>\n            <small>VISITOR JOURNAL</small>\n            <h2>{{ activeTab.title }}</h2>\n            <p>{{ activeTab.note }}</p>\n          </div>\n          <button class=\"line-button\" type=\"button\" @click=\"$emit('close-menu')\">返回</button>\n        </header>\n\n        <div class=\"customer-menu-content\">\n          <template v-if=\"view === 'today'\">\n            <div class=\"metric-grid three\">\n              <section class=\"metric-strip\">\n                <span>当前资金</span><strong>{{ yuan(state.资金) }}</strong>\n                <p>目前可以自由支配的余额。</p>\n              </section>\n              <section class=\"metric-strip\">\n                <span>住宿</span><strong>{{ stayText }}</strong>\n                <p>{{ state.住宿.状态 === '住宿中' ? state.住宿.房型 : '可以临时到店消费' }}</p>\n              </section>\n              <section class=\"metric-strip\">\n                <span>当前指名</span><strong>{{ state.当前指名?.员工 || '未指名' }}</strong>\n                <p>{{ nominationText }}</p>\n              </section>\n            </div>\n            <section class=\"data-strip spaced\">\n              <div class=\"strip-head\">\n                <h3>今天的安排</h3>\n                <span>{{ state.时间 }}</span>\n              </div>\n              <p v-if=\"state.当前服务\">\n                {{ state.当前服务.员工 }} · {{ state.当前服务.项目 }} · {{ state.当前服务.区域 }} ·\n                {{ state.当前服务.状态 }}\n              </p>\n              <p v-else>还没有预约服务，可以先查看今天在店的员工和项目。</p>\n              <div class=\"strip-actions\">\n                <button type=\"button\" @click=\"$emit('open-menu', 'projects')\">选择服务</button>\n                <button v-if=\"state.当前服务?.状态 === '已预约'\" type=\"button\" @click=\"$emit('start-service')\">\n                  开始服务\n                </button>\n                <button type=\"button\" @click=\"$emit('open-menu', 'areas')\">查看区域</button>\n              </div>\n            </section>\n            <section class=\"data-strip spaced\">\n              <div class=\"strip-head\">\n                <h3>今日记录</h3>\n                <span>{{ state.今日记录.length }}</span>\n              </div>\n              <p v-for=\"(entry, index) in state.今日记录.slice(-6).reverse()\" :key=\"`${index}-${entry}`\">{{ entry }}</p>\n            </section>\n          </template>\n\n          <template v-else-if=\"view === 'areas'\">\n            <section v-for=\"area in areas\" :key=\"area.名称\" class=\"data-strip\">\n              <div class=\"strip-head\">\n                <h3>{{ area.名称 }}</h3>\n                <span>{{ area.名称 === state.地点 ? '当前位置' : `${areaEmployees(area.名称).length}名员工` }}</span>\n              </div>\n              <p>{{ area.说明 }}</p>\n              <p>\n                在场：{{\n                  areaEmployees(area.名称)\n                    .map(item => item.姓名)\n                    .join('、') || '暂无'\n                }}\n              </p>\n              <p>\n                项目：{{\n                  areaProjects(area.名称)\n                    .map(item => item.名称)\n                    .join('、') || '暂无'\n                }}\n              </p>\n              <div class=\"strip-actions\">\n                <button type=\"button\" :disabled=\"area.名称 === state.地点 || busy\" @click=\"$emit('travel', area.名称)\">\n                  {{ area.名称 === state.地点 ? '已在这里' : '前往' }}\n                </button>\n              </div>\n            </section>\n          </template>\n\n          <template v-else-if=\"view === 'projects'\">\n            <section\n              v-for=\"project in projects\"\n              :key=\"project.名称\"\n              class=\"data-strip\"\n              :class=\"{ selected: selectedProject === project.名称 }\"\n            >\n              <div class=\"strip-head\">\n                <h3>{{ project.名称 }}</h3>\n                <span>{{ yuan(project.价格) }}</span>\n              </div>\n              <p>{{ project.区域 }} · {{ project.时长分钟 }}分钟 · {{ project.标签.join(' / ') }}</p>\n              <p>{{ project.说明 }}</p>\n              <div class=\"strip-actions\">\n                <button type=\"button\" :disabled=\"!project.开放\" @click=\"$emit('select-project', project.名称)\">\n                  {{ selectedProject === project.名称 ? '已选择' : '选择' }}\n                </button>\n              </div>\n            </section>\n            <section class=\"data-strip\">\n              <div class=\"strip-head\">\n                <h3>选择员工</h3>\n                <span>{{ availableProjectEmployees.length }}名可选</span>\n              </div>\n              <p v-if=\"availableProjectEmployees.length === 0\">今天暂时没有员工可以承接这个项目。</p>\n              <div v-else class=\"employee-selector\">\n                <button\n                  v-for=\"employee in availableProjectEmployees\"\n                  :key=\"employee.姓名\"\n                  type=\"button\"\n                  :class=\"{ 'is-active': selectedEmployee === employee.姓名 }\"\n                  @click=\"$emit('select-employee', employee.姓名)\"\n                >\n                  {{ employee.姓名 }} · {{ employee.评级 }}级 · {{ employee.状态 }}\n                </button>\n              </div>\n            </section>\n            <section class=\"selection-dock\">\n              <div>\n                <small>当前选择</small>\n                <strong>{{ selectedProject || '尚未选择项目' }}</strong>\n                <span>{{ selectedEmployee || '尚未选择员工' }}</span>\n              </div>\n              <button\n                type=\"button\"\n                :disabled=\"\n                  busy ||\n                  !selectedProject ||\n                  !selectedEmployee ||\n                  !availableProjectEmployees.some(employee => employee.姓名 === selectedEmployee)\n                \"\n                @click=\"$emit('book-service')\"\n              >\n                确认预约\n              </button>\n            </section>\n          </template>\n\n          <template v-else-if=\"view === 'nomination'\">\n            <section v-if=\"state.当前指名\" class=\"current-focus\">\n              <small>当前指名</small>\n              <strong>{{ state.当前指名.员工 }}</strong>\n              <p>剩余 {{ state.当前指名.剩余天数 }} 天 · 已付 {{ yuan(state.当前指名.已付费用) }}</p>\n              <button type=\"button\" :disabled=\"busy\" @click=\"$emit('end-nomination')\">结束指名</button>\n            </section>\n            <section\n              v-for=\"employee in employees\"\n              :key=\"employee.姓名\"\n              class=\"data-strip\"\n              :class=\"{ selected: selectedEmployee === employee.姓名 }\"\n            >\n              <div class=\"strip-head\">\n                <h3>{{ employee.姓名 }}</h3>\n                <span>{{ employee.评级 }}级 · {{ employee.状态 }}</span>\n              </div>\n              <p>{{ employee.区域 }} · 每日指名费 {{ yuan(employee.每日指名费) }}</p>\n              <p>好感 {{ employee.好感度 }} · 信任 {{ employee.信任度 }} · {{ relationStage(employee) }}</p>\n              <div class=\"strip-actions\">\n                <button type=\"button\" @click=\"$emit('select-employee', employee.姓名)\">\n                  {{ selectedEmployee === employee.姓名 ? '已选择' : '查看' }}\n                </button>\n                <button\n                  type=\"button\"\n                  :disabled=\"busy || Boolean(state.当前指名) || !canNominate(employee)\"\n                  @click=\"$emit('nominate', employee.姓名)\"\n                >\n                  指名\n                </button>\n              </div>\n            </section>\n          </template>\n\n          <template v-else-if=\"view === 'relationship'\">\n            <section v-if=\"selectedEmployeeData\" class=\"relationship-focus\">\n              <div class=\"relationship-title\">\n                <div>\n                  <small>{{ selectedEmployeeData.评级 }}级员工</small>\n                  <h3>{{ selectedEmployeeData.姓名 }}</h3>\n                </div>\n                <span>{{ relationStage(selectedEmployeeData) }}</span>\n              </div>\n              <p>{{ selectedEmployeeData.说明 }}</p>\n              <div class=\"relation-meter\">\n                <span>好感 {{ selectedEmployeeData.好感度 }}</span\n                ><i :style=\"{ width: `${selectedEmployeeData.好感度}%` }\" />\n              </div>\n              <div class=\"relation-meter trust\">\n                <span>信任 {{ selectedEmployeeData.信任度 }}</span\n                ><i :style=\"{ width: `${selectedEmployeeData.信任度}%` }\" />\n              </div>\n              <div class=\"relation-summary\">\n                <span>联系 {{ selectedEmployeeData.联系状态 }}</span>\n              </div>\n              <p>她对额外邀请的态度：{{ acceptance(selectedEmployeeData).label }}。</p>\n              <div class=\"strip-actions\">\n                <button type=\"button\" @click=\"$emit('talk', selectedEmployeeData.姓名)\">交谈</button>\n                <button\n                  type=\"button\"\n                  :disabled=\"selectedEmployeeData.联系状态 === '已添加'\"\n                  @click=\"$emit('request-contact', selectedEmployeeData.姓名)\"\n                >\n                  请求联系方式\n                </button>\n                <button type=\"button\" @click=\"$emit('extra', selectedEmployeeData.姓名)\">额外服务</button>\n                <button\n                  type=\"button\"\n                  :disabled=\"selectedEmployeeData.联系状态 !== '已添加'\"\n                  @click=\"$emit('invite', selectedEmployeeData.姓名)\"\n                >\n                  私下邀约\n                </button>\n                <button type=\"button\" @click=\"$emit('tip', selectedEmployeeData.姓名)\">打赏</button>\n              </div>\n            </section>\n            <div class=\"employee-selector\">\n              <button\n                v-for=\"employee in employees\"\n                :key=\"employee.姓名\"\n                type=\"button\"\n                :class=\"{ 'is-active': selectedEmployee === employee.姓名 }\"\n                @click=\"$emit('select-employee', employee.姓名)\"\n              >\n                {{ employee.姓名 }}\n              </button>\n            </div>\n          </template>\n\n          <template v-else-if=\"view === 'contacts'\">\n            <div class=\"contact-layout\">\n              <nav class=\"contact-list\" aria-label=\"联系人列表\">\n                <button\n                  v-for=\"contact in contactEmployees\"\n                  :key=\"contact.姓名\"\n                  type=\"button\"\n                  :class=\"{ 'is-active': selectedContact === contact.姓名 }\"\n                  @click=\"$emit('select-contact', contact.姓名)\"\n                >\n                  <span\n                    ><b>{{ contact.姓名 }}</b\n                    ><small>{{ contact.在线状态 }}</small></span\n                  >\n                  <em v-if=\"state.联系人[contact.姓名]?.未读\">{{ state.联系人[contact.姓名].未读 }}</em>\n                </button>\n                <p v-if=\"contactEmployees.length === 0\">还没有联系人。先在现场推进关系并请求联系方式。</p>\n              </nav>\n              <section class=\"message-panel\">\n                <template v-if=\"selectedContactData\">\n                  <header>\n                    <div>\n                      <strong>{{ selectedContactData.姓名 }}</strong\n                      ><span>{{ selectedContactData.在线状态 }} · {{ relationStage(selectedContactData) }}</span>\n                    </div>\n                    <button type=\"button\" :disabled=\"busy\" @click=\"$emit('invite', selectedContactData.姓名)\">\n                      邀约\n                    </button>\n                  </header>\n                  <div class=\"message-history\">\n                    <p v-if=\"selectedConversationMessages.length === 0\">还没有消息，先发一句问候。</p>\n                    <article\n                      v-for=\"message in selectedConversationMessages\"\n                      :key=\"message.id\"\n                      :class=\"{ mine: message.发送者 === '用户' }\"\n                    >\n                      <small>{{ message.发送者 }} · {{ message.时间 }}</small>\n                      <p>{{ message.内容 }}</p>\n                    </article>\n                  </div>\n                  <form class=\"message-compose\" @submit.prevent=\"sendMessage\">\n                    <input\n                      v-model=\"messageDraft\"\n                      type=\"text\"\n                      maxlength=\"1000\"\n                      placeholder=\"输入要发送的消息\"\n                      :disabled=\"busy\"\n                    />\n                    <button type=\"submit\" :disabled=\"busy || !messageDraft.trim()\">发送</button>\n                  </form>\n                </template>\n                <p v-else>从左侧选择联系人。</p>\n              </section>\n            </div>\n          </template>\n\n          <template v-else-if=\"view === 'schedule'\">\n            <div class=\"metric-grid three\">\n              <section class=\"metric-strip\">\n                <span>日期</span><strong>{{ state.日序 }}日目</strong>\n                <p>{{ state.日期 }}</p>\n              </section>\n              <section class=\"metric-strip\">\n                <span>当前时间</span><strong>{{ state.时间 }}</strong>\n                <p>{{ state.地点 }}</p>\n              </section>\n              <section class=\"metric-strip\">\n                <span>住宿剩余</span><strong>{{ state.住宿.剩余天数 }}</strong>\n                <p>{{ state.住宿.房型 || '未住宿' }}</p>\n              </section>\n            </div>\n            <section class=\"data-strip spaced\">\n              <div class=\"strip-head\">\n                <h3>住宿安排</h3>\n                <span>{{ state.住宿.状态 }}</span>\n              </div>\n              <template v-if=\"state.住宿.状态 === '未住宿'\">\n                <div class=\"stay-options\">\n                  <button\n                    v-for=\"room in roomOptions\"\n                    :key=\"room.名称\"\n                    type=\"button\"\n                    :class=\"{ 'is-active': selectedRoom === room.名称 }\"\n                    @click=\"selectedRoom = room.名称\"\n                  >\n                    {{ room.名称 }} · {{ yuan(room.每日房费) }}\n                  </button>\n                </div>\n                <label class=\"day-stepper\"\n                  ><span>住宿天数</span><input v-model.number=\"stayDays\" type=\"number\" min=\"1\" max=\"7\"\n                /></label>\n                <div class=\"strip-actions\">\n                  <button\n                    type=\"button\"\n                    :disabled=\"busy\"\n                    @click=\"$emit('check-in', { room: selectedRoom, days: stayDays })\"\n                  >\n                    办理住宿\n                  </button>\n                </div>\n              </template>\n              <template v-else>\n                <p>{{ state.住宿.房型 }} · 剩余 {{ state.住宿.剩余天数 }} 天 · 每日 {{ yuan(state.住宿.每日房费) }}</p>\n                <div class=\"strip-actions\">\n                  <button type=\"button\" :disabled=\"busy\" @click=\"$emit('check-out')\">办理退房</button>\n                </div>\n              </template>\n            </section>\n            <section class=\"data-strip spaced\">\n              <div class=\"strip-head\">\n                <h3>休息到次日</h3>\n                <span>09:00</span>\n              </div>\n              <p>结束今天的行程，明早九点继续。</p>\n              <div class=\"strip-actions\">\n                <button type=\"button\" :disabled=\"busy\" @click=\"$emit('rest-day')\">休息</button>\n              </div>\n            </section>\n          </template>\n\n          <template v-else-if=\"view === 'wallet'\">\n            <section class=\"wallet-total\">\n              <small>可用资金</small><strong>{{ yuan(state.资金) }}</strong>\n              <p>每一笔消费都会留在这里。</p>\n            </section>\n            <section v-for=\"entry in state.消费流水.slice().reverse()\" :key=\"entry.id\" class=\"ledger-row\">\n              <div>\n                <strong>{{ entry.名称 }}</strong\n                ><span>{{ entry.日期 }} · {{ entry.时间 }} · {{ entry.类型 }}</span>\n              </div>\n              <div>\n                <b>-{{ yuan(entry.金额) }}</b\n                ><small>余额 {{ yuan(entry.余额) }}</small>\n              </div>\n            </section>\n            <p v-if=\"state.消费流水.length === 0\" class=\"empty-note\">还没有消费记录。</p>\n          </template>\n        </div>\n      </article>\n    </section>\n\n    <section v-if=\"storyOpen\" class=\"customer-story-layer\" aria-label=\"正文阅读\">\n      <header>\n        <div>\n          <small>{{ state.日期 }} · {{ state.时间 }}</small>\n          <h2>{{ state.地点 }}</h2>\n        </div>\n        <button type=\"button\" @click=\"$emit('close-story')\">返回</button>\n      </header>\n      <article>\n        <p v-for=\"(paragraph, index) in storyParagraphs\" :key=\"index\">{{ paragraph }}</p>\n      </article>\n    </section>\n  </section>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue';\nimport {\n  CUSTOMER_ROOM_OPTIONS,\n  getCustomerExtraAcceptance,\n  getCustomerRelationshipStage,\n  listCustomerAvailableEmployees,\n  type CustomerEmployee,\n  type CustomerMenuView,\n  type CustomerPageState,\n} from './customerGame';\n\nconst props = defineProps<{\n  state: CustomerPageState;\n  menuOpen: boolean;\n  view: CustomerMenuView;\n  selectedEmployee: string;\n  selectedProject: string;\n  selectedContact: string;\n  storyOpen: boolean;\n  busy: boolean;\n  spriteUrl: string;\n}>();\n\nconst emit = defineEmits<{\n  'open-menu': [view: CustomerMenuView];\n  'close-menu': [];\n  travel: [areaName: string];\n  'select-employee': [employeeName: string];\n  'select-project': [projectName: string];\n  nominate: [employeeName: string];\n  'end-nomination': [];\n  'book-service': [];\n  'start-service': [];\n  'finish-service': [];\n  talk: [employeeName: string];\n  'request-contact': [employeeName: string];\n  extra: [employeeName: string];\n  invite: [employeeName: string];\n  tip: [employeeName: string];\n  'free-airp': [];\n  'next-dialogue': [];\n  'select-contact': [employeeName: string];\n  'send-message': [payload: { employeeName: string; text: string }];\n  'check-in': [payload: { room: string; days: number }];\n  'check-out': [];\n  'rest-day': [];\n  'close-story': [];\n}>();\n\nconst tabs: { key: CustomerMenuView; title: string; note: string }[] = [\n  { key: 'today', title: '今日', note: '当前安排、住宿和可继续的主要行动。' },\n  { key: 'areas', title: '区域', note: '前往店内不同区域，查看在场员工和项目。' },\n  { key: 'projects', title: '服务', note: '选择项目与员工，确认后进入服务现场。' },\n  { key: 'nomination', title: '指名', note: '按住宿剩余天数或单日完成指名。' },\n  { key: 'relationship', title: '关系', note: '查看好感、信任和可用的关系入口。' },\n  { key: 'contacts', title: '联系人', note: '线上聊天、未读消息和私下邀约。' },\n  { key: 'schedule', title: '行程', note: '住宿、今日时间和跨天安排。' },\n  { key: 'wallet', title: '资金', note: '单一余额与全部消费记录。' },\n];\n\nconst messageDraft = ref('');\nconst selectedRoom = ref(CUSTOMER_ROOM_OPTIONS[0].名称);\nconst stayDays = ref(1);\nconst roomOptions = CUSTOMER_ROOM_OPTIONS;\nconst activeTab = computed(() => tabs.find(tab => tab.key === props.view) ?? tabs[0]);\nconst employees = computed(() => Object.values(props.state.员工));\nconst projects = computed(() => Object.values(props.state.项目).filter(project => project.开放));\nconst areas = computed(() => Object.values(props.state.区域).filter(area => area.开放));\nconst availableProjectEmployees = computed(() =>\n  props.selectedProject ? listCustomerAvailableEmployees(props.state, props.selectedProject) : [],\n);\nconst selectedEmployeeData = computed(() => props.state.员工[props.selectedEmployee] ?? employees.value[0] ?? null);\nconst currentEmployee = computed(() => {\n  const preferredName = props.state.当前服务?.员工 ?? props.state.当前指名?.员工;\n  const preferred = preferredName ? props.state.员工[preferredName] : null;\n  if (preferred?.区域 === props.state.地点 && preferred.状态 !== '休息') return preferred;\n  return employees.value.find(employee => employee.区域 === props.state.地点 && employee.状态 !== '休息') ?? null;\n});\nconst relationshipStage = computed(() =>\n  currentEmployee.value ? getCustomerRelationshipStage(currentEmployee.value) : '初识',\n);\nconst dialoguePage = computed(\n  () =>\n    props.state.对话.台词页[props.state.对话.当前页] ?? {\n      speaker: props.state.对话.说话人,\n      text: '水汽沿着木廊慢慢散开。',\n    },\n);\nconst stayText = computed(() => (props.state.住宿.状态 === '住宿中' ? `${props.state.住宿.剩余天数}天` : '临时到店'));\nconst nominationText = computed(() =>\n  props.state.当前指名 ? `剩余${props.state.当前指名.剩余天数}天` : '可在指名页选择员工',\n);\nconst contactEmployees = computed(() => employees.value.filter(employee => employee.联系状态 === '已添加'));\nconst selectedContactData = computed(\n  () => props.state.员工[props.selectedContact] ?? contactEmployees.value[0] ?? null,\n);\nconst selectedConversationMessages = computed(() =>\n  selectedContactData.value ? (props.state.联系人[selectedContactData.value.姓名]?.消息 ?? []) : [],\n);\nconst storyParagraphs = computed(() =>\n  props.state.对话.最近正文\n    .split(/\\r?\\n+/)\n    .map(item => item.trim())\n    .filter(Boolean),\n);\n\nfunction yuan(value: number) {\n  return `¥${Math.round(value).toLocaleString('zh-CN')}`;\n}\n\nfunction relationStage(employee: CustomerEmployee) {\n  return getCustomerRelationshipStage(employee);\n}\n\nfunction acceptance(employee: CustomerEmployee) {\n  return getCustomerExtraAcceptance(employee);\n}\n\nfunction canNominate(employee: CustomerEmployee) {\n  return employee.状态 === '空闲' || employee.状态 === '指名待命';\n}\n\nfunction areaEmployees(areaName: string) {\n  return employees.value.filter(employee => employee.区域 === areaName && employee.状态 !== '休息');\n}\n\nfunction areaProjects(areaName: string) {\n  return projects.value.filter(project => project.区域 === areaName);\n}\n\nfunction sendMessage() {\n  const text = messageDraft.value.trim();\n  const employeeName = selectedContactData.value?.姓名 ?? '';\n  if (!text || !employeeName) return;\n  emit('send-message', { employeeName, text });\n  messageDraft.value = '';\n}\n</script>\n\n<style scoped>\n.customer-play-layer {\n  --c-text: #f7ecdc;\n  --c-muted: rgba(247, 236, 220, 0.64);\n  --c-line: rgba(247, 236, 220, 0.2);\n  --c-gold: #d7b36d;\n  --c-tea: #80aa9c;\n  position: absolute;\n  inset: 0;\n  z-index: 8;\n  color: var(--c-text);\n  pointer-events: none;\n}\n\nbutton,\ninput {\n  color: inherit;\n  font: inherit;\n}\n\nbutton {\n  borde