,iCACE,YAAa,CACb,OAAQ,CACR,gCACF,CAEA,sCACE,MAAO,CACP,YAAa,CACb,8BAAkC,CAClC,4BAAgC,CAChC,aAAc,CACd,iBACF,CAEA,2CACE,aACF,CAEA,+BACE,YAAa,CACb,6CAAgD,CAChD,gCACF,CAEA,mCACE,iBAAkB,CAClB,6BACF,CAEA,wEAEE,aAAc,CACd,4BAAgC,CAChC,aACF,CAEA,sCACE,aAAc,CACd,cAAe,CACf,aAAc,CACd,cACF,CAEA,6BACE,YAAa,CACb,eAAgB,CAChB,kBAAmB,CACnB,6BAA8B,CAC9B,cAAe,CACf,8CACF,CAEA,+BACE,aAAc,CACd,cAAe,CACf,eACF,CAEA,oCACE,aAAc,CACd,cACF,CAEA,4CACE,aACF,CAEA,6BACE,YAAa,CACb,4BAAgC,CAChC,cACF,CAEA,+BACE,YAAa,CACb,+BAAgC,CAChC,kBAAmB,CACnB,QAAS,CACT,YACF,CAEA,gCACE,YAAa,CACb,WAAY,CACZ,kBAAmB,CACnB,6CAAiD,CACjD,aAAc,CACd,iBAAkB,CAClB,cACF,CAEA,qCACE,aAAc,CACd,iBAAkB,CAClB,cACF,CAEA,gCACE,eACF,CAEA,mCACE,YAAa,CACb,8BAA+B,CAC/B,kBAAmB,CACnB,QACF,CAEA,qCACE,cACF,CAEA,0CACE,cACF,CAEA,0BACE,iBAAkB,CAClB,8CAAkD,CAClD,4BAAgC,CAChC,aACF,CAEA,yBACE,gCACE,OAAQ,CACR,WACF,CAEA,gCACE,oBACF,CAEA,iCACE,QAAS,CACT,QAAS,CACT,UAAW,CACX,WACF,CAEA,gDACE,YACF,CAEA,kCACE,QAAS,CACT,WAAY,CACZ,OAAQ,CACR,eAAgB,CAChB,8BACF,CAEA,gCACE,YACF,CAEA,oCACE,8BACF,CAEA,mCACE,iBACF,CAEA,mCACE,sBACF,CAEA,sGAGE,6CACF,CAEA,6BACE,6CACF,CAEA,6BACE,yBACF,CAEA,mCACE,8BACF,CAEA,qCACE,aACF,CACF,CAEA,yBACE,+DAEE,SACF,CAEA,+BACE,QACF,CAEA,gCACE,QAAS,CACT,WACF,CAEA,+BACE,QAAS,CACT,SAAU,CACV,UAAW,CACX,cACF,CAEA,+CACE,YACF,CAEA,gCACE,sBACF,CAEA,iCACE,UAAW,CACX,UAAW,CACX,WACF,CAEA,kCACE,8BACF,CAEA,gCACE,YAAa,CACb,cACF,CAEA,oCACE,yBAA0B,CAC1B,qCACF,CAEA,mCACE,YAAa,CACb,eAAgB,CAChB,6CAAgD,CAChD,0CAA6C,CAC7C,SAAU,CACV,cAAe,CACf,8CACF,CAEA,0CACE,WAAY,CACZ,YAAa,CACb,aAAc,CACd,6CAAiD,CACjD,eAAgB,CAChB,iBACF,CAEA,oDACE,gBAAiB,CACjB,+BACF,CAEA,mCACE,sBACF,CAEA,sCACE,cACF,CAEA,qCACE,YACF,CAEA,sGAGE,6BACF,CAEA,mCACE,8BAA+B,CAC/B,QAAS,CACT,iBACF,CAEA,+BACE,8BAA+B,CAC/B,QACF,CAEA,gCACE,WAAY,CACZ,cACF,CACF","sourcesContent":["<template>\n  <section class=\"waiter-play-layer\" :class=\"{ 'is-menu-open': menuOpen }\" aria-label=\"服务员玩法\">\n    <template v-if=\"!menuOpen\">\n      <header class=\"waiter-brand\">\n        <span class=\"waiter-seal\">汤</span>\n        <span><strong>未开之花</strong><small>在店服务</small></span>\n      </header>\n\n      <aside class=\"waiter-status\" aria-label=\"服务员状态\">\n        <div class=\"grade-plaque\">\n          <b>{{ state.grade }}</b>\n          <span>当前评级</span>\n        </div>\n        <div class=\"status-row\">\n          <span>体力</span><strong>{{ state.stamina }} / {{ state.maxStamina }}</strong>\n        </div>\n        <div class=\"stamina-track\"><i :style=\"{ width: `${staminaPercent}%` }\" /></div>\n        <div class=\"status-row\">\n          <span>岗位</span><strong>{{ state.shift.area }}</strong>\n        </div>\n        <div class=\"status-row\">\n          <span>余额</span><strong>{{ yuan(state.balance) }}</strong>\n        </div>\n      </aside>\n\n      <div class=\"waiter-clock\">\n        <span>{{ state.dateText }}</span>\n        <b>{{ state.time }}</b>\n        <span>{{ state.location }}</span>\n      </div>\n\n      <div class=\"waiter-sprite\" aria-hidden=\"true\">\n        <img :src=\"spriteUrl\" alt=\"\" />\n        <div class=\"sprite-caption\">\n          <strong>{{ state.workStatus }}</strong>\n          <span>{{ state.shift.name }} · 日薪 {{ yuan(state.dailySalary) }}</span>\n        </div>\n      </div>\n\n      <nav class=\"waiter-actions\" aria-label=\"服务员快捷操作\">\n        <template v-if=\"currentAssignment\">\n          <button type=\"button\" :disabled=\"busy\" @click=\"$emit('continue-service')\">\n            <span>继续接待</span><b>›</b>\n          </button>\n          <button type=\"button\" :disabled=\"busy\" @click=\"$emit('finish-service')\"><span>结束服务</span><b>■</b></button>\n        </template>\n        <template v-else>\n          <button\n            v-if=\"state.workStatus === '未上班' || state.workStatus === '休息中'\"\n            type=\"button\"\n            :disabled=\"busy\"\n            @click=\"$emit('start-shift')\"\n          >\n            <span>{{ state.workStatus === '休息中' ? '返回岗位' : '到岗' }}</span\n            ><b>＋</b>\n          </button>\n          <button\n            v-if=\"nextAssignment\"\n            type=\"button\"\n            :disabled=\"busy || state.workStatus === '未上班' || state.stamina < 12\"\n            @click=\"$emit('start-service', nextAssignment.id)\"\n          >\n            <span>{{ nextAssignment.source === '指名客' ? '指名接待' : '下一位客人' }}</span\n            ><b>›</b>\n          </button>\n          <button type=\"button\" :disabled=\"busy || state.workStatus === '未上班'\" @click=\"$emit('rest')\">\n            <span>休息</span><b>○</b>\n          </button>\n          <button type=\"button\" :disabled=\"busy\" @click=\"$emit('open-menu', 'growth')\">\n            <span>成长</span><b>↗</b>\n          </button>\n          <button type=\"button\" :disabled=\"busy\" @click=\"$emit('open-menu', 'finance')\">\n            <span>收支</span><b>¥</b>\n          </button>\n        </template>\n      </nav>\n\n      <button class=\"waiter-dialogue\" type=\"button\" @click=\"$emit('open-menu', 'shift')\">\n        <span class=\"dialogue-name\">{{ state.dialogue.speaker }}</span>\n        <span class=\"dialogue-body\">{{ state.dialogue.text }}</span>\n        <span class=\"dialogue-hint\">菜单</span>\n      </button>\n    </template>\n\n    <section v-if=\"menuOpen\" class=\"waiter-menu-layer\" aria-label=\"服务员菜单\">\n      <nav class=\"waiter-menu-tabs\" aria-label=\"服务员菜单分类\">\n        <button\n          v-for=\"tab in tabs\"\n          :key=\"tab.key\"\n          type=\"button\"\n          :class=\"{ 'is-active': view === tab.key }\"\n          @click=\"$emit('open-menu', tab.key)\"\n        >\n          {{ tab.title }}\n        </button>\n      </nav>\n\n      <article class=\"waiter-menu-main\">\n        <header class=\"waiter-menu-head\">\n          <div>\n            <small>STAFF RECORD</small>\n            <h2>{{ activeTab.title }}</h2>\n            <p>{{ activeTab.note }}</p>\n          </div>\n          <button class=\"line-button\" type=\"button\" @click=\"$emit('close-menu')\">返回</button>\n        </header>\n\n        <div class=\"waiter-menu-content\">\n          <template v-if=\"view === 'shift'\">\n            <div class=\"metric-grid three\">\n              <section class=\"metric-strip\">\n                <span>班次</span><strong>{{ state.shift.name }}</strong>\n                <p>{{ state.shift.start }} - {{ state.shift.end }}</p>\n              </section>\n              <section class=\"metric-strip\">\n                <span>工作状态</span><strong>{{ state.workStatus }}</strong>\n                <p>{{ state.location }}</p>\n              </section>\n              <section class=\"metric-strip\">\n                <span>今日接待</span><strong>{{ completedServices }} / {{ state.assignments.length }}</strong>\n                <p>指名客必须优先完成。</p>\n              </section>\n            </div>\n            <section class=\"data-strip spaced\">\n              <div class=\"strip-head\">\n                <h3>当前班次</h3>\n                <span>{{ state.shift.area }}</span>\n              </div>\n              <p>体力低时可以休息或进行身体护理。普通路线不需要完成任何额外服务。</p>\n              <div class=\"strip-actions\">\n                <button type=\"button\" :disabled=\"busy || !canStartShift\" @click=\"$emit('start-shift')\">到岗</button>\n                <button type=\"button\" :disabled=\"busy || !canRest\" @click=\"$emit('rest')\">休息</button>\n                <button type=\"button\" :disabled=\"busy || !canSettle\" @click=\"$emit('settle')\">下班结算</button>\n              </div>\n            </section>\n            <section v-if=\"state.latestSettlement\" class=\"settlement-strip\">\n              <small>最近结算 · {{ state.latestSettlement.date }}</small>\n              <strong>{{ signedYuan(state.latestSettlement.net) }}</strong>\n              <p>\n                收入 {{ yuan(state.latestSettlement.income) }} · 支出 {{ yuan(state.latestSettlement.expense) }} ·\n                {{ state.latestSettlement.services }} 次接待\n              </p>\n            </section>\n          </template>\n\n          <template v-else-if=\"view === 'service'\">\n            <section\n              v-for=\"assignment in state.assignments\"\n              :key=\"assignment.id\"\n              class=\"assignment-strip\"\n              :class=\"{ selected: selectedAssignmentId === assignment.id, nomination: assignment.source === '指名客' }\"\n            >\n              <div class=\"assignment-time\">\n                <b>{{ assignment.time }}</b\n                ><span>{{ assignment.durationMinutes }}分</span>\n              </div>\n              <div class=\"assignment-main\">\n                <div class=\"strip-head\">\n                  <h3>{{ assignment.guest }}</h3>\n                  <span>{{ assignment.source }}</span>\n                </div>\n                <p>{{ assignment.project }} · {{ assignment.area }}</p>\n                <small\n                  >{{ assignment.status\n                  }}<template v-if=\"assignment.nominationDays\">\n                    · 指名 {{ assignment.nominationDays }} 天</template\n                  ></small\n                >\n              </div>\n              <div class=\"assignment-actions\">\n                <button type=\"button\" @click=\"$emit('select-assignment', assignment.id)\">\n                  {{ selectedAssignmentId === assignment.id ? '已选择' : '查看' }}\n                </button>\n                <button\n                  type=\"button\"\n                  :disabled=\"\n                    busy ||\n                    assignment.status !== '待接待' ||\n                    state.workStatus === '未上班' ||\n                    Boolean(state.currentService)\n                  \"\n                  @click=\"$emit('start-service', assignment.id)\"\n                >\n                  开始\n                </button>\n              </div>\n            </section>\n          </template>\n\n          <template v-else-if=\"view === 'nomination'\">\n            <div class=\"metric-grid three\">\n              <section class=\"metric-strip\">\n                <span>累计指名</span><strong>{{ state.evaluation.nominationCount }}</strong>\n                <p>评级与形象投入会提高出现概率。</p>\n              </section>\n              <section class=\"metric-strip\">\n                <span>当日指名费</span><strong>{{ yuan(nominationFee) }}</strong>\n                <p>全额归你个人所有。</p>\n              </section>\n              <section class=\"metric-strip\">\n                <span>今日指名收入</span><strong>{{ yuan(state.todayIncome.指名费) }}</strong>\n                <p>完成当天指名接待后结算。</p>\n              </section>\n            </div>\n            <section v-if=\"state.activeNomination\" class=\"focus-strip\">\n              <small>当前跨天指名</small>\n              <strong>{{ state.activeNomination.guest }}</strong>\n              <p>\n                {{ state.activeNomination.project }} · {{ state.activeNomination.area }} · 剩余\n                {{ state.activeNomination.remainingDays }} 天\n              </p>\n            </section>\n            <section v-else class=\"data-strip\">\n              <div class=\"strip-head\">\n                <h3>暂无跨天指名</h3>\n                <span>{{ state.grade }}级</span>\n              </div>\n              <p>继续积累评价和回头客，指名安排会自然出现。</p>\n            </section>\n          </template>\n\n          <template v-else-if=\"view === 'growth'\">\n            <div class=\"metric-grid three\">\n              <section class=\"metric-strip\">\n                <span>标准完成</span><strong>{{ state.growth.标准服务.完成次数 }}</strong>\n                <p>标准路线的主要成长来源。</p>\n              </section>\n              <section class=\"metric-strip\">\n                <span>礼貌拒绝</span><strong>{{ state.growth.标准服务.礼貌拒绝次数 }}</strong>\n                <p>维持边界也会积累经验。</p>\n              </section>\n              <section class=\"metric-strip\">\n                <span>好评</span><strong>{{ state.growth.标准服务.好评次数 }}</strong>\n                <p>评级与日薪的重要依据。</p>\n              </section>\n            </div>\n            <section class=\"growth-section\">\n              <header>\n                <h3>熟练度</h3>\n                <span>由实际次数与个人投入换算</span>\n              </header>\n              <div class=\"skill-grid\">\n                <div v-for=\"(value, name) in state.skills\" :key=\"name\" class=\"skill-row\">\n                  <span>{{ name }}</span\n                  ><b>{{ value }}</b\n                  ><i><em :style=\"{ width: `${value}%` }\" /></i>\n                </div>\n              </div>\n            </section>\n            <section class=\"growth-section\">\n              <header>\n                <h3>客观结果</h3>\n                <span>只记录已经发生的结果</span>\n              </header>\n              <div class=\"count-grid\">\n                <span\n                  >胸部接触 <b>{{ state.growth.擦边记录.胸部接触次数 }}</b></span\n                >\n                <span\n                  >大腿接触 <b>{{ state.growth.擦边记录.大腿接触次数 }}</b></span\n                >\n                <span\n                  >隔衣摩擦 <b>{{ state.growth.擦边记录.隔衣摩擦次数 }}</b></span\n                >\n                <span\n                  >手交 <b>{{ state.growth.性服务记录.手交次数 }}</b></span\n                >\n                <span\n                  >口交 <b>{{ state.growth.性服务记录.口交次数 }}</b></span\n                >\n                <span\n                  >阴道性交 <b>{{ state.growth.性服务记录.阴道性交次数 }}</b></span\n                >\n                <span\n                  >肛交 <b>{{ state.growth.性服务记录.肛交次数 }}</b></span\n                >\n                <span\n                  >多人性服务 <b>{{ state.growth.性服务记录.多人性服务次数 }}</b></span\n                >\n              </div>\n            </section>\n            <section class=\"preserve-strip\">\n              <span :class=\"{ kept: state.growth.保持记录.未发生性服务 }\">未发生性服务</span>\n              <span :class=\"{ kept: state.growth.保持记录.阴道未插入 }\">阴道未插入</span>\n              <span :class=\"{ kept: state.growth.保持记录.肛门未插入 }\">肛门未插入</span>\n            </section>\n          </template>\n\n          <template v-else-if=\"view === 'finance'\">\n            <div class