/**
 * 服务员模式的生成提示词注入。
 *
 * 提供dialogue / story 两种场景的输出格式约束，
 * 通过 generate({ injects }) 单次注入，不污染全局 injectPrompts。
 * 不装入玩法事实；事实由世界书和MVU 变量块提供。
 */

export type WaiterGenerationKind = 'dialogue' | 'story';

type InjectItem = Omit<InjectionPrompt, 'id'>;

function makeWaiterDialoguePrompt(speaker: string): string {
  return [
    `[输出格式要求]`,
    `当前互动类型：对话。`,
    ``,
    `<content> 内只写当前说话人真正说出口的台词，每行格式：`,
    `角色名: 台词`,
    ``,
    `一行对应一页台词，可以有多行但保持简短。`,
    ...(speaker ? [`当前说话人：${speaker}。`] : []),
    ``,
    `禁止：`,
    `- 旁白、环境描写、动作描述`,
    `- 角色内心独白或心理分析`,
    `- 代替<user> 说话或行动`,
    `- 正文开头的孤立符号如 -`,
    `- 把变量更新写进<content>`,
    ``,
    `变量更新放在 </content> 之后按已有格式输出。`,
  ].join('\n');
}

function makeWaiterStoryPrompt(speaker: string | null): string {
  const speakerLine = speaker ? `当前互动对象：${speaker}。\n` : '';
  return [
    `[输出格式要求]`,
    `当前互动类型：接客正文。`,
    ``,
    `完整正文放在 <content>...</content> 中。`,
    `使用当前已激活的地点、项目、客人和当前接客事实继续场景。`,
    speakerLine,
    `可以描写：环境、客人动作、表情、语言以及成年人自愿的亲密内容。`,
    `只能承接<user> 已经明确输入的行动，不能替<user> 做出决定。`,
    ``,
    `禁止：`,
    `- 替<user> 接受额外服务`,
    `- 替 <user> 产生身体反应或心理态度`,
    `- 凭空宣布整次服务结束、结算、评价、打赏或晋级`,
    `- 思维链、分析、信息判定、心里话`,
    `- 把变量更新写进 <content>`,
    ``,
    `如果剧情确实推进时间，可在</content> 后输出：`,
    `<time>YYYY年MM月DD日 星期X HH:mm</time>`,
    `没有明确时间推进时不要输出。`,
    ``,
    `变量更新放在最后按已有格式输出。`,
  ].filter(line => line !== undefined).join('\n');
}

/**
 * 根据当前生成入口种类和说话人，构建服务员模式的单次注入提示词。
 * speaker 为空字符串或null 时，提示词不输出"当前说话人/互动对象"行。
 */
export function makeWaiterGenerationInjects(kind: WaiterGenerationKind, speaker: string | null = null): InjectItem[] {
  let content: string;
  switch (kind) {
    case 'dialogue':
      content = makeWaiterDialoguePrompt(speaker || '');
      break;
    case 'story':
      content = makeWaiterStoryPrompt(speaker || null);
      break;
    default:
      content = makeWaiterDialoguePrompt(speaker || '');
  }

  return [
    {
      position: 'in_chat',
      depth: 1,
      role: 'system',
      content,
      should_scan: false,
    },
  ];
}
